    "allocated": [
      {
        "0": 0.1
      },
      {
        "0": 0.2
      }
    ],
    "free_order": "reverse",
    "full_request_after_free_ok": false,
    "memory_after_final_check_repr": "0.9999999999999999",
    "restored_memory": 0.9999999999999999,
    "restored_memory_repr": "0.9999999999999999"
  },
